// Gradio owns focus, expanded state and visibility. Animate its layout changes
// after the native click has run, including clicks generated by the keyboard.
(() => {
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)');
  const transitions = new Map();

  function syncWaveform(event) {
    const audio = event.target;
    if (!(audio instanceof HTMLAudioElement)) return;
    const waveform = audio.closest('.monitor-recent')?.querySelector('.monitor-waveform');
    if (!waveform) return;
    const seek = waveform.querySelector('.wave-seek');
    seek.disabled = !!audio.error || !Number.isFinite(audio.duration) || audio.duration <= 0;
    const position = audio.currentTime || 0;
    const clock = Math.floor(position / 60) + ':' + String(Math.floor(position % 60)).padStart(2, '0');
    if (!seek.disabled) seek.max = audio.duration;
    seek.value = seek.disabled ? 0 : position;
    seek.setAttribute('aria-valuetext', clock);
    waveform.style.setProperty('--played', (seek.disabled ? 0 : 100 * position / audio.duration) + '%');
    const caption = waveform.querySelector('.wave-time');
    if (caption.textContent !== clock) caption.textContent = clock;
  }
  for (const name of ['durationchange', 'loadedmetadata', 'timeupdate', 'emptied', 'error']) {
    document.addEventListener(name, syncWaveform, true);
  }
  document.addEventListener('input', (event) => {
    const seek = event.target;
    if (!seek.matches?.('.wave-seek') || seek.disabled) return;
    const audio = seek.closest('.monitor-recent').querySelector('audio');
    if (audio && Number.isFinite(audio.duration)) audio.currentTime = Math.min(audio.duration, seek.valueAsNumber);
  });

  document.addEventListener('keydown', (event) => {
    if (event.defaultPrevented || event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const tab = event.target.closest?.('#main-tabs [role="tablist"] > [role="tab"]');
    if (!tab || !['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return;
    const tabs = Array.from(tab.parentElement.querySelectorAll('[role="tab"]:not([aria-disabled="true"])'));
    const index = tabs.indexOf(tab);
    if (index < 0) return;
    let next;
    if (event.key === 'Home') next = tabs[0];
    else if (event.key === 'End') next = tabs[tabs.length - 1];
    else next = tabs[(index + (event.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length];
    event.preventDefault();
    next.focus({preventScroll: true});
    next.click();
  });

  function finish(panel) {
    const current = transitions.get(panel);
    if (!current) return;
    transitions.delete(panel);
    cancelAnimationFrame(current.frame);
    current.animation?.cancel();
    panel.removeAttribute('data-fold-moving');
  }

  document.addEventListener('click', (event) => {
    if (reduced.matches || !(event.target instanceof Element)) return;
    const header = event.target.closest('#page .gr-accordion > button.label-wrap, #page details.parts > summary');
    if (!header || typeof header.animate !== 'function') return;
    const panel = header.parentElement;
    const from = panel.getBoundingClientRect().height;
    finish(panel);
    const transition = {frame: 0, animation: null};
    transitions.set(panel, transition);
    transition.frame = requestAnimationFrame(() => {
      const to = panel.getBoundingClientRect().height;
      if (!panel.isConnected || reduced.matches || Math.abs(to - from) < 2) {
        finish(panel);
        return;
      }
      panel.setAttribute('data-fold-moving', '');
      const animation = panel.animate([{height: from + 'px'}, {height: to + 'px'}], {
        duration: to > from ? 220 : 165,
        easing: 'cubic-bezier(.2,0,.25,1)'
      });
      transition.animation = animation;
      animation.onfinish = () => {
        if (transitions.get(panel) === transition) finish(panel);
      };
    });
  }, true);

  reduced.addEventListener('change', () => {
    if (reduced.matches) transitions.forEach((_, panel) => finish(panel));
  });
})();
